// ========================================
// Gesture Conductor — Visual Module
// ========================================
// Features:
// - Static vertical gradients in active instrument zones.
// - Animated musician silhouettes.
// - Highlighted palm markers without pulsing.
// - Fixed-colour floating notes.
// - Local particle forces generated by moving hands.
//
// Shared settings and state come from config.js.
// Hand data and coordinate conversion come from gesture.js.


// ========================================
// Instrument Colours
// ========================================
// Strings: blue; woodwinds: green; brass: orange.

const zoneColours = [
  [75, 135, 220],
  [55, 165, 120],
  [230, 145, 55]
];


// ========================================
// Static Gradient Backgrounds
// ========================================

function drawZoneHighlights() {
  const performing =
    introState === "playing" && !editMode;

  if (!performing) return;

  const zoneWidth = width / 3;

  push();

  colorMode(RGB, 255);
  rectMode(CORNER);
  noStroke();

  for (let group = 0; group < 3; group++) {
    if (!activeHandGroups.has(group)) continue;

    const base = zoneColours[group];

    // Fixed light colour at the top of the zone.
    const topColour = base.map(
      (channel) => channel + (255 - channel) * 0.72
    );

    // Fixed deeper colour at the bottom of the zone.
    const bottomColour = base.map(
      (channel) => channel * 0.75
    );

    const left = group * zoneWidth;

    // Each horizontal strip has a colour based only on its height.
    // Time and hand height do not affect the gradient.
    for (let y = 0; y < height; y++) {
      const amount = y / Math.max(1, height - 1);

      const r = lerp(
        topColour[0],
        bottomColour[0],
        amount
      );

      const g = lerp(
        topColour[1],
        bottomColour[1],
        amount
      );

      const b = lerp(
        topColour[2],
        bottomColour[2],
        amount
      );

      fill(r, g, b, 165);
      rect(left, y, zoneWidth, 1);
    }
  }

  pop();
}


// ========================================
// Musician Image Loading
// ========================================

function loadMusicianImages() {
  imageMode(CORNER);

  for (let i = 0; i < imagePaths.length; i++) {
    const player = {
      img: null,

      // Four consecutive images belong to each instrument group.
      group: floor(i / 4),

      // Offset the animation timing between musicians.
      phase: i * 0.6,

      // Visual activation level, not measured audio loudness.
      energy: 0
    };

    players.push(player);

    loadImage(
      imagePaths[i],

      (img) => {
        player.img = img;
        loadedCount++;
      },

      () => {
        failedFiles.push(imagePaths[i]);

        console.error(
          "Image loading failed:",
          imagePaths[i]
        );
      }
    );
  }
}


// ========================================
// Musician Rendering and Movement
// ========================================

function drawOrchestra() {
  // Draw backgrounds before the musician silhouettes.
  drawZoneHighlights();

  const performing =
    introState === "playing" && !editMode;

  if (loadedCount < imagePaths.length) return;

  for (let i = 0; i < players.length; i++) {
    const player = players[i];
    const box = getPlayerBox(i);

    const target =
      performing && activeHandGroups.has(player.group)
        ? 1
        : 0;

    player.energy = lerp(
      player.energy,
      target,
      0.08
    );

    const wave =
      sin(millis() / 200 + player.phase);

    const sway = editMode
      ? 0
      : wave * 0.025 * player.energy;

    const pulse = editMode
      ? 1
      : 1 + (wave + 1) * 0.02 * player.energy;

    push();

    // Animate around the image's bottom-centre anchor.
    translate(box.x, box.y);
    rotate(sway);
    scale(pulse);

    push();

    // Mirror only the image, keeping editor labels readable.
    scale(layout[i].flip ? -1 : 1, 1);

    image(
      player.img,
      -box.w / 2,
      -box.h,
      box.w,
      box.h
    );

    pop();

    if (editMode) {
      if (selected === i) {
        noFill();
        stroke(0);
        strokeWeight(1.5);

        rect(
          -box.w / 2,
          -box.h,
          box.w,
          box.h
        );
      }

      noStroke();
      fill(0);
      textAlign(CENTER, TOP);
      textSize(12);

      text(
        String(i + 1).padStart(2, "0"),
        0,
        5
      );
    }

    pop();
  }
}


// ========================================
// Responsive Musician Bounds
// ========================================

function getPlayerBox(i) {
  const img = players[i].img;
  const item = layout[i];

  const screenScale = min(
    width / 1200,
    height / 600
  );

  const h =
    item.size * screenScale * globalSize;

  return {
    x: item.x * width,
    y: item.y * height,
    w: h * img.width / img.height,
    h
  };
}


// Preserve the main program's call without labels or dividers.
function drawInterface() {}


// ========================================
// Virtual Hands and Static Palm Highlights
// ========================================

function drawVirtualHands() {
  if (editMode) return;

  const performing = introState === "playing";
  const now = millis();

  push();

  for (const hand of trackedHands) {
    const points =
      hand.keypoints.map(handToScreen);

    const center = handToScreen(hand);

    const group = constrain(
      hand.group,
      0,
      2
    );

    const [r, g, b] = zoneColours[group];

    // Dim a retained track if its detection is no longer fresh.
    const fresh =
      now - hand.lastSeen <= introFreshHandMs;

    const strength = fresh ? 1 : 0.35;

    noFill();
    stroke(
      performing ? 25 : 240,
      220 * strength
    );
    strokeWeight(2.5);

    for (const [a, b] of handConnections) {
      line(
        points[a].x,
        points[a].y,
        points[b].x,
        points[b].y
      );
    }

    for (const i of [4, 8, 12, 16, 20]) {
      circle(
        points[i].x,
        points[i].y,
        7
      );
    }

    // Keep the marker size fixed: no breathing or flashing effect.
    const diameter = 28;

    // Static translucent layers create a soft halo.
    noStroke();

    fill(r, g, b, 12 * strength);
    circle(center.x, center.y, diameter + 30);

    fill(r, g, b, 24 * strength);
    circle(center.x, center.y, diameter + 16);

    fill(r, g, b, 48 * strength);
    circle(center.x, center.y, diameter);

    // White outline maintains contrast on the stage and curtains.
    noFill();
    stroke(255, 230 * strength);
    strokeWeight(5);
    circle(center.x, center.y, diameter);

    stroke(r, g, b, 255 * strength);
    strokeWeight(3);
    circle(center.x, center.y, diameter);

    noStroke();
    fill(r, g, b, 255 * strength);
    circle(center.x, center.y, 7);
  }

  pop();
}


// ========================================
// Floating Note Settings
// ========================================

const floatingNotes = [];
const noteSymbols = ["♪", "♫", "♩", "♬"];

const lastNoteSpawnAt = [null, null, null];

const noteSpawnInterval = 220;
const maxFloatingNotes = 80;

const handNoteRadius = 180;
const handNotePush = 3;

let noteAnimationLastAt = null;
let previousNoteHands = [];


// ========================================
// Particle Simulation and Rendering
// ========================================

function drawFloatingNotes() {
  const now = millis();

  const performing =
    introState === "playing" &&
    !editMode &&
    !document.hidden;

  if (!performing) {
    floatingNotes.length = 0;
    lastNoteSpawnAt.fill(null);
    noteAnimationLastAt = null;
    previousNoteHands = [];
    return;
  }

  const elapsed = noteAnimationLastAt === null
    ? 0
    : (now - noteAnimationLastAt) / 1000;

  const continuous =
    elapsed > 0 && elapsed <= 0.15;

  // Limit simulation steps after a rendering delay.
  const dt = Math.min(
    Math.max(elapsed, 0),
    0.05
  );

  noteAnimationLastAt = now;

  const freshHands = trackedHands.filter((hand) => {
    return (
      now - hand.lastSeen <= introFreshHandMs &&
      hand.group >= 0 &&
      hand.group < 3
    );
  });

  const handForces = getNoteHandForces(
    freshHands,
    continuous ? elapsed : 0
  );

  // Generate one stream for each zone containing a fresh hand.
  for (let group = 0; group < 3; group++) {
    const hasHand = freshHands.some(
      (hand) => hand.group === group
    );

    if (!hasHand) {
      lastNoteSpawnAt[group] = null;
      continue;
    }

    const due =
      lastNoteSpawnAt[group] === null ||
      now - lastNoteSpawnAt[group] >=
        noteSpawnInterval;

    if (due) {
      spawnFloatingNote(group, now);
      lastNoteSpawnAt[group] = now;
    }
  }

  push();

  textAlign(CENTER, CENTER);
  textFont("Arial");
  noStroke();

  for (let i = floatingNotes.length - 1; i >= 0; i--) {
    const note = floatingNotes[i];
    const age = (now - note.bornAt) / 1000;

    if (
      age >= note.lifetime ||
      note.y < -note.size * 2
    ) {
      floatingNotes.splice(i, 1);
      continue;
    }

    // Apply gentle natural sideways drift.
    let forceX =
      Math.sin(
        age * note.swaySpeed + note.phase
      ) * 20;

    let forceY = 0;

    // Moving hands affect nearby particles.
    for (const hand of handForces) {
      const dx = note.x - hand.x;
      const dy = note.y - hand.y;
      const distance = Math.hypot(dx, dy);

      if (
        distance >= handNoteRadius ||
        hand.speed < 20
      ) {
        continue;
      }

      const influence = Math.pow(
        1 - distance / handNoteRadius,
        2
      );

      forceX +=
        hand.vx * handNotePush * influence;

      forceY +=
        hand.vy * handNotePush * influence;

      // Add outward spreading from the palm position.
      if (distance > 1) {
        const spread =
          Math.min(hand.speed, 500) *
          0.8 *
          influence;

        forceX += dx / distance * spread;
        forceY += dy / distance * spread;
      }
    }

    const forceLength = Math.hypot(
      forceX,
      forceY
    );

    if (forceLength > 1200) {
      forceX *= 1200 / forceLength;
      forceY *= 1200 / forceLength;
    }

    note.vx += forceX * dt;
    note.vy += forceY * dt;

    // Reduce sideways momentum after disturbance.
    note.vx *= Math.exp(-1.5 * dt);

    // Gradually restore the original upward speed.
    const recovery =
      1 - Math.exp(-1.8 * dt);

    note.vy +=
      (-note.riseSpeed - note.vy) *
      recovery;

    note.vx = constrain(
      note.vx,
      -220,
      220
    );

    // Negative y velocity keeps notes moving upwards.
    note.vy = constrain(
      note.vy,
      -180,
      -8
    );

    note.x += note.vx * dt;
    note.y += note.vy * dt;

    // Keep notes within their original instrument zone.
    if (note.x < note.left) {
      note.x = note.left;
      note.vx = Math.abs(note.vx) * 0.35;
    }

    if (note.x > note.right) {
      note.x = note.right;
      note.vx = -Math.abs(note.vx) * 0.35;
    }

    const fadeIn =
      Math.min(age / 0.15, 1);

    const fadeOut = Math.max(
      0,
      1 - age / note.lifetime
    );

    // Fixed RGB colour; opacity changes only to fade the note.
    const alpha =
      240 * fadeIn * fadeOut;

    const [r, g, b] = note.colour;

    push();

    translate(note.x, note.y);

    rotate(
      constrain(
        note.vx / 500,
        -0.35,
        0.35
      ) +
      Math.sin(age * 2 + note.phase) * 0.08
    );

    fill(r, g, b, alpha);
    textSize(note.size);
    text(note.symbol, 0, 0);

    pop();
  }

  pop();
}


// ========================================
// Hand Velocity Estimation
// ========================================

function getNoteHandForces(hands, dt) {
  const currentHands = hands.map((hand) => {
    const point = handToScreen(hand);

    return {
      x: point.x,
      y: point.y,
      vx: 0,
      vy: 0,
      speed: 0
    };
  });

  const candidates = [];

  if (dt > 0) {
    for (let i = 0; i < currentHands.length; i++) {
      for (let j = 0; j < previousNoteHands.length; j++) {
        const distance = Math.hypot(
          currentHands[i].x -
            previousNoteHands[j].x,

          currentHands[i].y -
            previousNoteHands[j].y
        );

        candidates.push({
          i,
          j,
          distance
        });
      }
    }
  }

  candidates.sort(
    (a, b) => a.distance - b.distance
  );

  const usedCurrent = new Set();
  const usedPrevious = new Set();

  const matchDistance =
    Math.min(width, height) * 0.3;

  // Match by proximity; crossing hands can create ambiguity.
  for (const { i, j, distance } of candidates) {
    if (
      usedCurrent.has(i) ||
      usedPrevious.has(j) ||
      distance > matchDistance
    ) {
      continue;
    }

    usedCurrent.add(i);
    usedPrevious.add(j);

    const current = currentHands[i];
    const previous = previousNoteHands[j];

    current.vx =
      (current.x - previous.x) / dt;

    current.vy =
      (current.y - previous.y) / dt;

    const speed = Math.hypot(
      current.vx,
      current.vy
    );

    // Limit extreme estimates caused by tracking jumps.
    if (speed > 800) {
      current.vx *= 800 / speed;
      current.vy *= 800 / speed;
    }

    current.speed = Math.min(speed, 800);
  }

  previousNoteHands = currentHands.map((hand) => ({
    x: hand.x,
    y: hand.y
  }));

  return currentHands;
}


// ========================================
// Generate Notes Above the Musicians
// ========================================

function spawnFloatingNote(group, now) {
  const musicianBoxes = [];

  for (let i = 0; i < players.length; i++) {
    if (
      players[i].group === group &&
      players[i].img
    ) {
      musicianBoxes.push(getPlayerBox(i));
    }
  }

  if (!musicianBoxes.length) return;

  if (floatingNotes.length >= maxFloatingNotes) {
    floatingNotes.shift();
  }

  const zoneWidth = width / 3;

  const inset = Math.min(
    24,
    zoneWidth * 0.2
  );

  const left =
    group * zoneWidth + inset;

  const right =
    (group + 1) * zoneWidth - inset;

  // Image bounds include transparent PNG margins.
  const highestTop = Math.min(
    ...musicianBoxes.map(
      (box) => box.y - box.h
    )
  );

  const musician = random(musicianBoxes);
  const noteSize = random(22, 36);
  const riseSpeed = random(35, 60);

  floatingNotes.push({
    symbol: random(noteSymbols),

    // A fixed darker instrument colour improves visibility.
    // Hand height and particle height do not change this colour.
    colour: zoneColours[group].map(
      (channel) => channel * 0.75
    ),

    x: constrain(
      musician.x +
        random(
          -musician.w * 0.25,
          musician.w * 0.25
        ),
      left,
      right
    ),

    y:
      highestTop -
      noteSize -
      random(10, 25),

    left,
    right,
    size: noteSize,

    vx: random(-8, 8),
    vy: -riseSpeed,
    riseSpeed,

    swaySpeed: random(1.5, 2.5),
    phase: random(TWO_PI),

    lifetime: random(2.5, 3.5),
    bornAt: now
  });
}